StickerLibraryDialog::StickerLibraryDialog(CWnd* owner,CString data,CString base,std::function<bool(const CString&,const CString&,CString&)> save):owner_(owner),expected_(std::move(data)),base_(std::move(base)),save_(std::move(save)){CString error;if(!services::DecodeStickerLibrary(expected_,entries_,error))throw std::runtime_error("Invalid sticker library");}
INT_PTR StickerLibraryDialog::Run(){struct Template{DLGTEMPLATE t{};WORD menu=0,cls=0,title=0;}r;r.t.style=WS_POPUP|WS_CAPTION|WS_SYSMENU|DS_MODALFRAME|WS_CLIPCHILDREN;r.t.cx=480;r.t.cy=300;InitModalIndirect(&r.t,owner_);return DoModal();}
BOOL StickerLibraryDialog::OnInitDialog(){CDialog::OnInitDialog();dpi_=LayoutDpi(m_hWnd);BindText(*this,Text::StickerLibrary);const DWORD style=WS_CHILD|WS_VISIBLE;list_.Create(style|WS_BORDER|WS_TABSTOP|LVS_REPORT|LVS_SINGLESEL|LVS_SHOWSELALWAYS,CRect(),this,StickerList);list_.SetExtendedStyle(LVS_EX_FULLROWSELECT|LVS_EX_DOUBLEBUFFER);for(auto text:{Text::StickerName,Text::StickerPath,Text::StickerStatus})list_.InsertColumn(list_.GetHeaderCtrl()->GetItemCount(),Tr(text));help_.Create(Tr(Text::StickerHelp),style,CRect(),this);BindText(help_,Text::StickerHelp);status_.Create(L"",style,CRect(),this);auto button=[&](CButton& c,Text text,UINT id){c.Create(Tr(text),style|WS_TABSTOP|(id==IDOK?BS_DEFPUSHBUTTON:0),CRect(),this,id);BindText(c,text);};button(add_,Text::StickerAdd,StickerAdd);button(rename_,Text::StickerRename,StickerRename);button(remove_,Text::StickerRemove,StickerRemove);button(saveButton_,Text::StickerSave,StickerSave);button(ok_,Text::StickerInsert,IDOK);button(cancel_,Text::Cancel,IDCANCEL);ApplyFont(*this,font_);Rebuild(entries_.empty()?-1:0);Layout();CenterWindow(owner_);if(initAudit_){initAudit_(*this);job_.cancel=true;KillTimer(1);if(inserted.Empty())EndDialog(IDCANCEL);return FALSE;}SetTimer(1,16,nullptr);Queue();return TRUE;}
int StickerLibraryDialog::Selected()const{return list_.GetNextItem(-1,LVNI_SELECTED);}
HBITMAP StickerLibraryDialog::Bitmap(const core::Image& image){BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=image.width;info.bmiHeader.biHeight=-image.height;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;void* pixels=nullptr;HBITMAP bitmap=CreateDIBSection(nullptr,&info,DIB_RGB_COLORS,&pixels,nullptr,0);if(bitmap&&pixels)memcpy(pixels,image.pixels.data(),image.pixels.size());return bitmap;}
void StickerLibraryDialog::Rebuild(int selected){++generation_;side_=std::clamp(Px(m_hWnd,48),16,128);list_.SetImageList(nullptr,LVSIL_SMALL);if(images_.GetSafeHandle())images_.DeleteImageList();images_.Create(side_,side_,ILC_COLOR32,32,1);list_.SetImageList(&images_,LVSIL_SMALL);list_.DeleteAllItems();core::Image blank;blank.Create(side_,side_);for(size_t i=0;i<blank.pixels.size();i+=4){blank.pixels[i]=blank.pixels[i+1]=blank.pixels[i+2]=235;blank.pixels[i+3]=255;}CBitmap bitmap;bitmap.Attach(Bitmap(blank));loaded_.assign(entries_.size(),false);failed_.assign(entries_.size(),false);for(size_t i=0;i<entries_.size();++i){const int icon=images_.Add(&bitmap,static_cast<CBitmap*>(nullptr));list_.InsertItem(int(i),entries_[i].name,icon);list_.SetItemText(int(i),1,entries_[i].path);list_.SetItemText(int(i),2,Tr(Text::StickerLoading));}if(selected>=0&&selected<int(entries_.size()))list_.SetItemState(selected,LVIS_SELECTED|LVIS_FOCUSED,LVIS_SELECTED|LVIS_FOCUSED);RefreshButtons();}
void StickerLibraryDialog::RefreshButtons(){list_.EnableWindow(!inserting_);const bool selected=Selected()>=0&&!inserting_;add_.EnableWindow(!inserting_&&entries_.size()<32);rename_.EnableWindow(selected);remove_.EnableWindow(selected);saveButton_.EnableWindow(!inserting_);ok_.EnableWindow(selected);}
void StickerLibraryDialog::Queue(){if(job_.Busy()||modal_)return;size_t index=entries_.size();if(inserting_)index=requested_;else for(size_t i=0;i<loaded_.size();++i)if(!loaded_[i]){index=i;break;}if(index>=entries_.size()){SetTimer(1,250,nullptr);return;}const auto generation=generation_;const CString path=services::StickerPath(entries_[index].path,base_);const auto loader=loaderAudit_;const int side=side_;const bool insert=inserting_;job_.Start([path,index,generation,loader,side,insert]{Result r;r.index=index;r.generation=generation;r.insert=insert;try{auto image=loader?loader(path):services::LoadSticker(path);r.image=insert?std::move(image):services::StickerThumbnail(image,side);}catch(const std::exception& e){r.error.Format(L"%hs",e.what());}return r;});SetTimer(1,16,nullptr);}
void StickerLibraryDialog::OnTimer(UINT_PTR){if(modal_)return;auto r=job_.Take();if(r&&r->generation==generation_){if(!r->error.IsEmpty()){if(inserting_){inserting_=false;RefreshButtons();}status_.SetWindowText(Tr(Text::StickerFailed));if(r->generation==generation_&&r->index<entries_.size()){loaded_[r->index]=true;failed_[r->index]=true;list_.SetItemText(int(r->index),2,Tr(Text::StickerFailed));}}else if(r->generation==generation_&&r->index<entries_.size()){if(r->insert){inserted=std::move(r->image);KillTimer(1);EndDialog(IDOK);return;}CBitmap bitmap;bitmap.Attach(Bitmap(r->image));if(bitmap.GetSafeHandle())images_.Replace(int(r->index),&bitmap,static_cast<CBitmap*>(nullptr));loaded_[r->index]=true;list_.SetItemText(int(r->index),2,Tr(Text::StickerReady));}}Queue();}
bool StickerLibraryDialog::Save(){CString data,error;if(!services::EncodeStickerLibrary(entries_,data,error)){status_.SetWindowText(error);return false;}const HWND host=m_hWnd;const auto save=save_;const bool saved=save(data,expected_,error);if(!::IsWindow(host)||CWnd::FromHandlePermanent(host)!=this)return false;if(!saved){status_.SetWindowText(error);return false;}expected_=data;status_.SetWindowText(Tr(Text::StickerSaved));return true;}
void StickerLibraryDialog::AddFiles(const std::vector<CString>& files){auto proposed=entries_;for(const auto& path:files){const CString stored=services::PortableStickerPath(path,base_);if(std::any_of(proposed.begin(),proposed.end(),[&](const auto& e){return e.path.CompareNoCase(stored)==0;}))continue;CString name=std::filesystem::path(path.GetString()).stem().c_str();name=name.Left(80);proposed.push_back({name,stored});}CString data,error;if(!services::EncodeStickerLibrary(proposed,data,error)){status_.SetWindowText(Tr(Text::StickerLimit));return;}entries_=std::move(proposed);Rebuild(entries_.empty()?-1:int(entries_.size()-1));Queue();}
void StickerLibraryDialog::OnAction(UINT id){if(inserting_)return;if(id==StickerAdd&&addFilesAudit_){AddFiles(addFilesAudit_());return;}if(id==StickerSave){Save();return;}const int selected=Selected();if(id==StickerRemove){if(selected<0)return;entries_.erase(entries_.begin()+selected);Rebuild(std::min(selected,int(entries_.size())-1));Queue();return;}const HWND host=m_hWnd;modal_=true;try{if(id==StickerAdd){CFileDialog dialog(TRUE,L"png",nullptr,OFN_FILEMUSTEXIST|OFN_NOCHANGEDIR|OFN_ALLOWMULTISELECT,Tr(Text::PngOnlyFilter),this);std::vector<wchar_t> buffer(65536);dialog.GetOFN().lpstrFile=buffer.data();dialog.GetOFN().nMaxFile=DWORD(buffer.size());const auto answer=dialog.DoModal();if(!::IsWindow(host)||CWnd::FromHandlePermanent(host)!=this)return;modal_=false;if(answer==IDOK){std::vector<CString> files;POSITION at=dialog.GetStartPosition();while(at){if(files.size()>=32){status_.SetWindowText(Tr(Text::StickerLimit));return;}files.push_back(dialog.GetNextPathName(at));}AddFiles(files);}}else if(id==StickerRename&&selected>=0){const auto generation=generation_;FormDialog dialog(this,Text::StickerRename,{{Text::StickerName,entries_[selected].name}});const auto answer=renameAudit_?renameAudit_(dialog):dialog.Run();if(!::IsWindow(host)||CWnd::FromHandlePermanent(host)!=this)return;modal_=false;if(answer==IDOK&&generation==generation_&&selected<int(entries_.size())){auto proposed=entries_;proposed[selected].name=dialog.Fields()[0].value;CString data,error;if(services::EncodeStickerLibrary(proposed,data,error)){entries_=std::move(proposed);list_.SetItemText(selected,0,entries_[selected].name);}else status_.SetWindowText(error);}}}catch(const std::exception& e){if(!::IsWindow(host)||CWnd::FromHandlePermanent(host)!=this)return;modal_=false;CString message;message.Format(L"%s %hs",Tr(Text::Failed),e.what());status_.SetWindowText(message);}if(::IsWindow(host)&&CWnd::FromHandlePermanent(host)==this)modal_=false;}
void StickerLibraryDialog::OnOK(){if(inserting_||Selected()<0||!Save())return;requested_=size_t(Selected());inserting_=true;RefreshButtons();Queue();}
void StickerLibraryDialog::OnCancel(){job_.cancel=true;KillTimer(1);CDialog::OnCancel();}
void StickerLibraryDialog::OnSelection(NMHDR*,LRESULT* result){*result=0;RefreshButtons();}
void StickerLibraryDialog::Layout(){MONITORINFO m{sizeof(m)};GetMonitorInfo(MonitorFromWindow(m_hWnd,MONITOR_DEFAULTTONEAREST),&m);if(workAreaAudit_.cx>0&&workAreaAudit_.cy>0){m.rcWork.right=m.rcWork.left+workAreaAudit_.cx;m.rcWork.bottom=m.rcWork.top+workAreaAudit_.cy;}CRect decoration(0,0,0,0);AdjustClientRect(decoration,*this);const int gap=Px(m_hWnd,10),row=Px(m_hWnd,30),w=std::min(Px(m_hWnd,900),std::max(430,int(m.rcWork.right-m.rcWork.left)-decoration.Width()-gap*2)),h=std::min(Px(m_hWnd,580),std::max(330,int(m.rcWork.bottom-m.rcWork.top)-decoration.Height()-gap*2));const int bottom=h-gap-row;int x=gap,y=gap;for(CButton* b:{&add_,&rename_,&remove_,&saveButton_}){CString text;b->GetWindowText(text);const int width=TextWidth(*b,text,16);if(x+width>w-gap){x=gap;y+=row+gap;}b->MoveWindow(x,y,width,row);x+=width+gap;}const int helpY=y+row+gap,helpHeight=row*2,listY=helpY+helpHeight+gap;help_.MoveWindow(gap,helpY,w-gap*2,helpHeight);list_.MoveWindow(gap,listY,w-gap*2,std::max(1,bottom-gap*2-row-listY));list_.SetColumnWidth(0,(w-gap*2)*30/100);list_.SetColumnWidth(1,(w-gap*2)*47/100);list_.SetColumnWidth(2,(w-gap*2)*23/100);status_.MoveWindow(gap,bottom-row-gap,w-gap*2,row);const int okWidth=std::max(Px(m_hWnd,140),TextWidth(ok_,Tr(Text::StickerInsert),20)),cancelWidth=std::max(Px(m_hWnd,90),TextWidth(cancel_,Tr(Text::Cancel),20));ok_.MoveWindow(w-gap*2-okWidth-cancelWidth,bottom,okWidth,row);cancel_.MoveWindow(w-gap-cancelWidth,bottom,cancelWidth,row);CRect window(0,0,w,h);AdjustClientRect(window,*this);SetWindowPos(nullptr,0,0,window.Width(),window.Height(),SWP_NOMOVE|SWP_NOZORDER);Invalidate(TRUE);}
LRESULT StickerLibraryDialog::OnLanguageChanged(WPARAM,LPARAM){RefreshBoundText(m_hWnd);int i=0;for(auto key:{Text::StickerName,Text::StickerPath,Text::StickerStatus}){CString text=Tr(key);LVCOLUMN c{};c.mask=LVCF_TEXT;c.pszText=text.GetBuffer();list_.SetColumn(i++,&c);text.ReleaseBuffer();}for(size_t n=0;n<entries_.size();++n)list_.SetItemText(int(n),2,Tr(!loaded_[n]?Text::StickerLoading:failed_[n]?Text::StickerFailed:Text::StickerReady));Layout();return 0;}
LRESULT StickerLibraryDialog::OnDpiChanged(WPARAM,LPARAM value){ScaleDialog(*this,font_,dpi_,value);const int selected=Selected();Rebuild(selected);Layout();Queue();return 0;}
